extra_css:
/* Darkroom surfaces: matte black boards lit by the safelight. Panels are near-black with a red cast that is brighter toward the
   top-left (where the safelight hangs), a dim red rim and a soft drop; hover lifts the board into the light and its rim warms to the
   safelight amber. Headings in warm print white. Scoped to own surfaces only. */
html[data-atmo="darkroom"] .card, html[data-atmo="darkroom"] .panel, html[data-atmo="darkroom"] .gx-card {
  background: radial-gradient(120% 90% at 0% 0%, rgba(255,60,30,.08), transparent 55%), linear-gradient(180deg, rgba(32,16,14,.9), rgba(12,6,6,.95));
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  box-shadow: inset 0 1px 0 rgba(255,140,110,.1), inset 0 0 0 1px rgba(255,90,60,.13), 0 18px 46px rgba(0,0,0,.75);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="darkroom"] .card:hover, html[data-atmo="darkroom"] .gx-card:hover {
  transform: translateY(-2px);
  background: radial-gradient(120% 90% at 0% 0%, rgba(255,70,35,.14), transparent 60%), linear-gradient(180deg, rgba(38,18,16,.92), rgba(14,7,6,.95));
  box-shadow: inset 0 1px 0 rgba(255,170,130,.18), inset 0 0 0 1px rgba(255,163,107,.42), 0 0 26px rgba(255,70,40,.12), 0 22px 54px rgba(0,0,0,.78); }
html[data-atmo="darkroom"] h1, html[data-atmo="darkroom"] h2 { background: linear-gradient(180deg, #fff6f2, #ffcdbd 52%, #c98571); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="darkroom"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

